import type { ReactNode } from "react";

export type IconProps = {
  className?: string;
  active?: boolean;
};

const GREEN = "#96BF47";
const NAVY = "#073E74";

function NavBadge({
  active,
  className,
  children,
}: {
  active?: boolean;
  className?: string;
  children: ReactNode;
}) {
  return (
    <svg
      width="48"
      height="48"
      viewBox="0 0 48 48"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
    >
      <rect
        x="4.75"
        y="4.75"
        width="40"
        height="40"
        rx="7.25"
        fill={active ? GREEN : "none"}
        stroke={GREEN}
        strokeWidth="1.5"
      />
      {children}
    </svg>
  );
}

function PlaceholderGlyph({ children }: { children: ReactNode }) {
  return (
    <g
      transform="translate(14 14) scale(0.8333)"
      stroke={NAVY}
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      fill="none"
    >
      {children}
    </g>
  );
}

